onClick:
{{
  Insert_Client_Rapide.run()
    .then((res) => {
      // 1. On récupère l'ID du client fraîchement créé (grâce à ton RETURNING)
      const newClientId = res[0].ID_Client;

      // 2. On le met en mémoire pour dire à la page Détail Client qui afficher
      return storeValue('detail_client_id', newClientId);
    })
    .then(() => storeValue('page_precedente', 'Clients')) // Pour que le bouton Retour de la fiche fonctionne
    .then(() => Get_Clients.run()) // On rafraîchit ton tableau en arrière-plan
    .then(() => {
      // 3. On ferme la modale, on affiche une notification et on ouvre la fiche !
      closeModal('modal_add_client_rapide');
      showAlert('Client créé avec succès !', 'success');
      navigateTo('Détail Client', {}, 'SAME_WINDOW');
    })
    .catch((err) => {
      showAlert('Erreur lors de la création : ' + err.message, 'error');
    });
}}
